const payload = $json.body ?? $json;

// GitHub sends a ping when a webhook is created. Deletions and other actions stop here.
if (typeof payload.zen === 'string' || payload.action !== 'created') return [];

const username = payload.sender?.login;
const repository = payload.repository?.full_name;
if (!username || !repository) {
  throw new Error('Malformed GitHub star event: sender.login and repository.full_name are required');
}

return [{
  json: {
    username,
    repository,
    starredAt: payload.starred_at ?? null
  }
}];

