const profile = $('Fetch GitHub User Profile').item.json;
const event = $('Parse & Validate Star Event').item.json;
const pitch = String($json.response ?? $json.text ?? $json.content ?? $json.candidates?.[0]?.content?.parts?.[0]?.text ?? $json.parts?.[0]?.text ?? $json.message?.content ?? $json.output_text ?? '').replace(/\s+/g, ' ').trim();
if (!pitch) throw new Error('AI node returned an empty sales pitch');

const trimTo = (value, max) => {
  const text = String(value ?? '').trim();
  return text.length <= max ? text : text.slice(0, max - 3) + '...';
};

return [{
  json: {
    username: 'Lead Sniper',
    embeds: [{
      title: 'High-Value GitHub Star Detected',
      url: profile.html_url || `https://github.com/${profile.login}`,
      description: `**${trimTo(profile.name || profile.login, 120)}** (@${profile.login}) starred **${trimTo(event.repository, 150)}**.`,
      color: 5793266,
      thumbnail: profile.avatar_url ? { url: profile.avatar_url } : undefined,
      fields: [
        { name: 'Bio', value: trimTo(profile.bio || 'Not provided', 1024), inline: false },
        { name: 'Company', value: trimTo(profile.company || 'Not provided', 1024), inline: true },
        { name: 'Influence', value: `${profile.followers} followers | ${profile.public_repos} public repos`, inline: true },
        { name: 'AI Sales Pitch', value: trimTo(pitch, 1024), inline: false }
      ],
      footer: { text: 'Lead Sniper - automated by n8n' }
    }]
  }
}];
